      if(pending==null){byte[] master=StreamingAttachmentCipher.newFileKey();List<AttachmentManifest600.File> result=new ArrayList<>();List<Path> created=new ArrayList<>();boolean saved=false;Set<String> names=new HashSet<>();try{String candidate=HexFormat.of().formatHex(master);for(Path source:paths){check();String name=source.getFileName().toString();PlainMessage.validateFilename(name);if(!names.add(name.toLowerCase(Locale.ROOT)))throw new IOException("Имена вложений должны различаться");var context=new StreamingAttachmentCipher.Context(UUID.randomUUID().toString(),local.identity().userId(),recipient.userId(),Files.size(source));Path spool=spool(context.transferId(),false);quota(StreamingAttachmentCipher.ciphertextSize(context.plaintextBytes()));byte[] key=AttachmentManifest600.fileKey(candidate,context.transferId());try{Files.createFile(spool,AtomicFiles.attributes(spools));created.add(spool);try(var in=Files.newInputStream(source,LinkOption.NOFOLLOW_LINKS);var out=FileChannel.open(spool,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS)){var encrypted=StreamingAttachmentCipher.encrypt(in,java.nio.channels.Channels.newOutputStream(out),context,key,this::active);out.force(true);result.add(new AttachmentManifest600.File(name,context,encrypted.ciphertextBytes(),encrypted.plaintextSha256(),encrypted.ciphertextSha256(),Math.addExact(local.now(),ttlMillis),ttlMillis));}}finally{Arrays.fill(key,(byte)0);}}
        pending=new AttachmentManifest600(audience,false,result,master);pendingFingerprint=fingerprint;save();saved=true;
      }finally{Arrays.fill(master,(byte)0);if(!saved){if(pending!=null){pending.close();pending=null;}pendingFingerprint=null;for(var file:created)Files.deleteIfExists(file);}}}
      for(var file:pending.files()){check();Path encrypted=spool(file.context().transferId(),false);remote.upload(encrypted,file.remote(local.now()),this::active,progress);}
      check();byte[] raw=pending.keyPayload(),wrapped=null;try{boolean protect=password.length>0;wrapped=protect?LetterEnvelope.seal(HexFormat.of().formatHex(raw),password,code):raw.clone();check();return new AttachmentManifest600(audience,protect,pending.files(),wrapped);}finally{Arrays.fill(raw,(byte)0);if(wrapped!=null)Arrays.fill(wrapped,(byte)0);}
