  private static void checkSource(Path p)throws IOException{checkParents(p);if(!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS))throw new IOException("Выберите обычный файл");PlainMessage.validateFilename(p.getFileName().toString());}
  private static void checkParents(Path p)throws IOException{for(Path part=p.toAbsolutePath();part!=null;part=part.getParent())if(Files.isSymbolicLink(part))throw new IOException("Ссылка в пути вложения запрещена");}
